// Explicit legacy fixtures for regression tests only. Never imported by the application.
import {createOperationalStore} from '../../../interno/operational-store.js';
const remoteQuotes=createOperationalStore('quotes');
export async function loadQuotes(){if(false){await remoteQuotes.load();const rows=remoteQuotes.list();quotes.splice(0,quotes.length,...rows);}return quotes;}
async function remoteQuoteAction(q,action,payload){const result=await remoteQuotes.run(action,q?.id||null,payload);const saved=result.record||result;if(q){for(const key of Object.keys(q))delete q[key];Object.assign(q,saved);}else quotes.unshift(saved);return saved;}
import {normalizeSearch} from '../../../shared/filters.js';
export const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
export const validDate=value=>/^\d{4}-\d{2}-\d{2}$/.test(value)&&!Number.isNaN(Date.parse(value+'T12:00:00Z'))&&new Date(value+'T12:00:00Z').toISOString().slice(0,10)===value;
export const money=cents=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(cents/100);
export function parsePrice(value){const s=String(value).trim();if(!/^\d+(?:[,.]\d{1,2})?$/.test(s))throw new Error('Informe um preço positivo, como 12,50, sem separador de milhares.');const cents=Math.round(Number(s.replace(',','.'))*100);if(!Number.isSafeInteger(cents)||cents<=0||cents>100000000)throw new Error('Informe um preço entre R$ 0,01 e R$ 1.000.000,00.');return cents;}
export function parseQuantity(value){const s=String(value).trim();if(!/^\d+(?:[,.]\d{1,3})?$/.test(s))throw new Error('Use uma quantidade positiva com até três casas decimais.');const number=Number(s.replace(',','.'));if(number<=0||number>1000000)throw new Error('Quantidade deve ser maior que zero e até 1.000.000.');return number;}
export const lineTotal=(cents,quantity)=>Number((BigInt(cents)*BigInt(Math.round(quantity*1000))+500n)/1000n);
export const quotes=[];
export const getQuote=id=>quotes.find(q=>q.id===id);
export function filterQuotes({status='open',query='',category='',start='',end=''}={}){if((start&&!validDate(start))||(end&&!validDate(end)))throw new Error('Informe datas válidas.');if(start&&end&&start>end)throw new Error('A data inicial não pode ser posterior à data final.');const needle=normalizeSearch(query);return quotes.filter(q=>q.status===status&&(!start||q.date>=start)&&(!end||q.date<=end)&&(!category||q.items.some(i=>i.category===category))&&(!needle||normalizeSearch([q.title,...q.items.map(i=>i.name),...q.providers.map(p=>p.name)].join(' ')).includes(needle)));}
function local_createQuote({title,date,items,providers}){if(false)return remoteQuoteAction(null,'create',{title,date,items,providers});if(!String(title||'').trim()||!validDate(date))throw new Error('Preencha o título e uma data válida.');if(!items.length)throw new Error('Adicione pelo menos um produto.');if(!providers.length)throw new Error('Adicione pelo menos um fornecedor.');const itemCopies=items.map(i=>({...i,id:crypto.randomUUID(),quantity:parseQuantity(i.quantity)}));const q={id:crypto.randomUUID(),title:String(title).trim(),date,status:'open',items:itemCopies,providers:providers.map(p=>({...p})),offers:{},awards:{}};quotes.unshift(q);return q;}
function assertOpen(q){if(!q||q.status!=='open')throw new Error('Esta cotação não está aberta para alterações.');}
export const isProviderFinalized=(q,providerId)=>Object.hasOwn(q.finalizedProviders||{},providerId);
export const isQuoteItemFinalized=(q,itemId)=>Object.values(q.finalizedProviders||{}).some(provider=>provider.items.some(item=>item.id===itemId));
function assertEditableItem(q,itemId){if(!q.items.some(item=>item.id===itemId))throw new Error('Produto inválido.');if(isQuoteItemFinalized(q,itemId))throw new Error('Este produto pertence a um fornecedor finalizado.');}
function assertEditableProvider(q,providerId){if(isProviderFinalized(q,providerId))throw new Error('Este fornecedor já foi finalizado.');}
function providerSnapshot(provider){if(!provider.items.length)throw new Error('Aprove pelo menos um produto para este fornecedor.');if(!Number.isSafeInteger(provider.total)||provider.total<=0)throw new Error('Total aprovado inválido.');return {...structuredClone(provider),finalizedAt:new Date().toISOString()};}
function local_finalizeQuoteProvider(q,providerId){if(false)return remoteQuoteAction(q,'finalizeQuoteProvider',{providerId});assertOpen(q);const provider=awardedByProvider(q).find(provider=>provider.id===providerId);if(!provider)throw new Error('Fornecedor inválido.');if(isProviderFinalized(q,providerId))return structuredClone(q.finalizedProviders[providerId]);const snapshot=providerSnapshot(provider);q.finalizedProviders={...q.finalizedProviders,[providerId]:snapshot};return structuredClone(snapshot);}

function local_setOffer(q,itemId,providerId,value){if(false)return remoteQuoteAction(q,'setOffer',{itemId,providerId,value});assertOpen(q);if(!q.items.some(i=>i.id===itemId)||!q.providers.some(p=>p.id===providerId))throw new Error('Item ou fornecedor inválido.');assertEditableItem(q,itemId);assertEditableProvider(q,providerId);q.offers[itemId]??={};if(String(value).trim()===''){delete q.offers[itemId][providerId];if(q.awards[itemId]===providerId)delete q.awards[itemId];return;}q.offers[itemId][providerId]=parsePrice(value);}
function local_chooseProvider(q,itemId,providerId){if(false)return remoteQuoteAction(q,'chooseProvider',{itemId,providerId});assertOpen(q);assertEditableItem(q,itemId);if(providerId!==null)assertEditableProvider(q,providerId);if(providerId===null){delete q.awards[itemId];return;}if(!q.providers.some(p=>p.id===providerId)||!Number.isInteger(q.offers[itemId]?.[providerId]))throw new Error('Preencha um preço válido antes de selecionar.');q.awards[itemId]=providerId;}
export function comparison(q,itemId){if(false)return q.computed?.comparisons?.[itemId]||{min:null,lowest:[],priced:0};const entries=q.providers.map(p=>({providerId:p.id,cents:q.offers[itemId]?.[p.id]})).filter(x=>Number.isInteger(x.cents));const min=entries.length?Math.min(...entries.map(x=>x.cents)):null;return {min,lowest:entries.filter(x=>x.cents===min).map(x=>x.providerId),priced:entries.length};}
export function totals(q){if(false)return q.computed?.totals||[];return q.providers.map(p=>{const complete=q.items.every(i=>Number.isInteger(q.offers[i.id]?.[p.id]));const subtotal=q.items.reduce((sum,i)=>sum+(Number.isInteger(q.offers[i.id]?.[p.id])?lineTotal(q.offers[i.id][p.id],i.quantity):0),0);return {...p,complete,total:complete?subtotal:null,subtotal};});}
export const selectedTotal=q=>false?(q.computed?.selectedTotal??0):q.items.reduce((sum,i)=>sum+(q.awards[i.id]?lineTotal(q.offers[i.id][q.awards[i.id]],i.quantity):0),0);
function local_finalizeQuote(q){if(false)return remoteQuoteAction(q,'finalizeQuote',{});assertOpen(q);if(!q.items.every(i=>q.awards[i.id]&&Number.isInteger(q.offers[i.id]?.[q.awards[i.id]])))throw new Error('Selecione manualmente um fornecedor para cada produto.');const snapshots=awardedByProvider(q).filter(provider=>provider.items.length).map(provider=>isProviderFinalized(q,provider.id)?q.finalizedProviders[provider.id]:providerSnapshot(provider));q.finalizedProviders=Object.fromEntries(snapshots.map(provider=>[provider.id,provider]));q.status='finished';return q;}
function local_updateItemQuantity(q,itemId,value){if(false)return remoteQuoteAction(q,'updateItemQuantity',{itemId,value});assertOpen(q);const item=q.items.find(i=>i.id===itemId);if(!item)throw new Error('Produto inválido.');assertEditableItem(q,itemId);const quantity=parseQuantity(value);if(item.quantity!==quantity){item.quantity=quantity;delete q.awards[itemId];}return item;}
function local_addQuoteProvider(q,provider){if(false)return remoteQuoteAction(q,'addQuoteProvider',{provider});assertOpen(q);if(!provider?.id||!String(provider.name||'').trim())throw new Error('Fornecedor inválido.');if(q.providers.some(p=>p.id===provider.id))throw new Error('Este fornecedor já está vinculado.');q.providers.push({id:provider.id,name:provider.name});}
function local_removeQuoteProvider(q,providerId,{clearLinked=false}={}){if(false)return remoteQuoteAction(q,'removeQuoteProvider',{providerId,clearLinked});assertOpen(q);if(!q.providers.some(p=>p.id===providerId))throw new Error('Fornecedor inválido.');assertEditableProvider(q,providerId);if(q.providers.length<=1)throw new Error('Mantenha pelo menos um fornecedor na cotação.');if(!clearLinked&&q.items.some(i=>Number.isInteger(q.offers[i.id]?.[providerId])||q.awards[i.id]===providerId))throw new Error('Remova os preços e escolhas deste fornecedor em Produtos antes de desvincular.');if(clearLinked)for(const item of q.items){if(q.offers[item.id])delete q.offers[item.id][providerId];if(q.awards[item.id]===providerId)delete q.awards[item.id];}q.providers=q.providers.filter(p=>p.id!==providerId);}
function local_addQuoteItem(q,product,quantity){if(false)return remoteQuoteAction(q,'addQuoteItem',{product,quantity});assertOpen(q);if(!product?.id||!product.name)throw new Error('Selecione um produto cadastrado.');if(q.items.some(item=>item.productId===product.id))throw new Error('Este produto já está na cotação.');const item={id:crypto.randomUUID(),productId:product.id,name:product.name,category:product.category,unit:product.unit,quantity:parseQuantity(quantity)};q.items.push(item);return item;}
export function awardedByProvider(q){if(false)return q.computed?.awardedByProvider||[];return q.providers.map(provider=>{const items=q.items.filter(item=>q.awards[item.id]===provider.id&&Number.isInteger(q.offers[item.id]?.[provider.id])).map(item=>({...item,unitPrice:q.offers[item.id][provider.id],total:lineTotal(q.offers[item.id][provider.id],item.quantity)}));return {...provider,items,total:items.reduce((sum,item)=>sum+item.total,0)};});}

export const quoteLineTotal=(q,itemId,providerId)=>false?(q.computed?.lineTotals?.[itemId]?.[providerId]??null):lineTotal(q.offers[itemId]?.[providerId],q.items.find(item=>item.id===itemId).quantity);

function computeFixture(q){const proposed=totals(q),complete=proposed.filter(p=>p.complete),minimum=complete.length?Math.min(...complete.map(p=>p.total)):null;q.computed={totals:proposed,awardedByProvider:awardedByProvider(q),selectedTotal:selectedTotal(q),minimumCompleteTotal:minimum,lowestCompleteCount:complete.filter(p=>p.total===minimum).length,comparisons:Object.fromEntries(q.items.map(item=>[item.id,comparison(q,item.id)])),lineTotals:Object.fromEntries(q.items.map(item=>[item.id,Object.fromEntries(q.providers.filter(p=>Number.isInteger(q.offers[item.id]?.[p.id])).map(p=>[p.id,lineTotal(q.offers[item.id][p.id],item.quantity)]))]))};return q;}
export const createQuote=(...args)=>computeFixture(local_createQuote(...args));
export const finalizeQuoteProvider=(q,...args)=>{const result=local_finalizeQuoteProvider(q,...args);computeFixture(q);return result;};
export const setOffer=(q,...args)=>{const result=local_setOffer(q,...args);computeFixture(q);return result;};
export const chooseProvider=(q,...args)=>{const result=local_chooseProvider(q,...args);computeFixture(q);return result;};
export const finalizeQuote=(q,...args)=>{const result=local_finalizeQuote(q,...args);computeFixture(q);return result;};
export const updateItemQuantity=(q,...args)=>{const result=local_updateItemQuantity(q,...args);computeFixture(q);return result;};
export const addQuoteProvider=(q,...args)=>{const result=local_addQuoteProvider(q,...args);computeFixture(q);return result;};
export const removeQuoteProvider=(q,...args)=>{const result=local_removeQuoteProvider(q,...args);computeFixture(q);return result;};
export const addQuoteItem=(q,...args)=>{const result=local_addQuoteItem(q,...args);computeFixture(q);return result;};
